14	export async function readMarkdownFiles(contentDir: string): Promise<string[]> {
15	  if (!fs.existsSync(contentDir)) {
16	    throw new Error(`Content directory not found: ${contentDir}`);
17	  }
18	
19	  const files = fs.readdirSync(contentDir);
20	  return files.filter((file) => file.endsWith('.md'));
21	}
22	
23	export async function parseMarkdownFile(
24	  filePath: string
25	): Promise<PageData> {
26	  const content = fs.readFileSync(filePath, 'utf-8');
27	  const { frontmatter, content: markdown } = parseFrontmatter(content);
28	  const html = markdownToHtml(markdown);
29	  const filename = path.basename(filePath);
30	  const slug = filename.replace(/\.md$/, '');
31	
32	  return {
33	    slug,
34	    filename,
35	    frontmatter,
36	    content: markdown,
37	    html,
38	  };
39	}
