41	export async function generatePages(
42	  contentDir: string,
43	  outputDir: string
44	): Promise<PageData[]> {
45	  if (!fs.existsSync(outputDir)) {
46	    fs.mkdirSync(outputDir, { recursive: true });
47	  }
48	
49	  const files = await readMarkdownFiles(contentDir);
50	  const pages: PageData[] = [];
51	
52	  for (const file of files) {
53	    const filePath = path.join(contentDir, file);
54	    const pageData = await parseMarkdownFile(filePath);
55	    pages.push(pageData);
56	
57	    const outputPath = path.join(outputDir, `${pageData.slug}.html`);
58	    const html = generatePageHtml(pageData);
59	    fs.writeFileSync(outputPath, html, 'utf-8');
60	  }
61	
62	  return pages;
63	}
