65	export function generatePageHtml(page: PageData): string {
66	  const title = page.frontmatter.title || page.slug;
67	  const date = page.frontmatter.date ? `<p class="date">${page.frontmatter.date}</p>` : '';
68	  const tags =
69	    page.frontmatter.tags && Array.isArray(page.frontmatter.tags)
70	      ? `<div class="tags">${page.frontmatter.tags
71	          .map((tag) => `<span class="tag">${escapeHtml(String(tag))}</span>`)
72	          .join('')}</div>`
73	      : '';
74	
75	  return `<!DOCTYPE html>
76	<html lang="en">
77	<head>
78	  <meta charset="UTF-8">
79	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
80	  <title>${escapeHtml(title)}</title>
81	  <style>
82	    body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; max-width: 800px; margin: 0 auto; padding: 20px; line-height: 1.6; }
83	    h1, h2, h3 { margin-top: 1.5em; }
84	    .date { color: #666; font-size: 0.9em; }
85	    .tags { margin: 10px 0; }
86	    .tag { display: inline-block; background: #f0f0f0; padding: 4px 8px; margin: 4px 4px 4px 0; border-radius: 4px; font-size: 0.85em; }
87	    a { color: #0066cc; }
88	  </style>
89	</head>
90	<body>
91	  <a href="index.html">← Back to Index</a>
92	  <article>
93	    <h1>${escapeHtml(title)}</h1>
94	    ${date}
95	    ${tags}
96	    <div class="content">
97	      ${page.html}
98	    </div>
99	  </article>
100	</body>
101	</html>`;
102	}
103	
104	export function generateIndexHtml(pages: PageData[]): string {
105	  const sortedPages = pages.sort((a, b) => {
106	    const dateA = new Date(String(a.frontmatter.date) || 0).getTime();
107	    const dateB = new Date(String(b.frontmatter.date) || 0).getTime();
108	    return dateB - dateA;
109	  });
110	
111	  const pagesList = sortedPages
112	    .map((page) => {
113	      const title = page.frontmatter.title || page.slug;
114	      const date = page.frontmatter.date ? ` — ${page.frontmatter.date}` : '';
115	      return `<li><a href="${page.slug}.html">${escapeHtml(title)}</a>${date}</li>`;
116	    })
117	    .join('\n    ');
118	
119	  return `<!DOCTYPE html>
120	<html lang="en">
121	<head>
122	  <meta charset="UTF-8">
123	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
124	  <title>Site Index</title>
125	  <style>
126	    body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; max-width: 800px; margin: 0 auto; padding: 20px; line-height: 1.6; }
127	    h1 { margin-bottom: 1.5em; }
128	    ul { list-style: none; padding: 0; }
129	    li { margin: 12px 0; }
130	    a { color: #0066cc; text-decoration: none; }
131	    a:hover { text-decoration: underline; }
132	  </style>
133	</head>
134	<body>
135	  <h1>Site Index</h1>
136	  <ul>
137	    ${pagesList}
138	  </ul>
139	</body>
140	</html>`;
141	}
