143	export async function build(
144	  contentDir: string = './content',
145	  outputDir: string = './dist'
146	): Promise<void> {
147	  if (!fs.existsSync(outputDir)) {
148	    fs.mkdirSync(outputDir, { recursive: true });
149	  }
150	
151	  const pages = await generatePages(contentDir, outputDir);
152	  const indexHtml = generateIndexHtml(pages);
153	  fs.writeFileSync(path.join(outputDir, 'index.html'), indexHtml, 'utf-8');
154	}
