156	function escapeHtml(text: string): string {
157	  const escapeMap: { [key: string]: string } = {
158	    '&': '&amp;',
159	    '<': '&lt;',
160	    '>': '&gt;',
161	    '"': '&quot;',
162	    "'": '&#39;',
163	  };
164	  return text.replace(/[&<>"']/g, (char) => escapeMap[char]);
165	}
