1	export interface Frontmatter {
2	  title?: string;
3	  date?: string;
4	  tags?: string[];
5	  [key: string]: unknown;
6	}
7	
8	export interface ParsedMarkdown {
9	  frontmatter: Frontmatter;
10	  content: string;
11	}
12	
13	function parseYamlValue(value: string): unknown {
14	  value = value.trim();
15	
16	  if (value === 'true') return true;
17	  if (value === 'false') return false;
18	  if (value === 'null' || value === '') return null;
19	
20	  if (!isNaN(Number(value))) return Number(value);
21	
22	  if (value.startsWith('[') && value.endsWith(']')) {
23	    const arrayContent = value.slice(1, -1).trim();
24	    if (!arrayContent) return [];
25	    return arrayContent.split(',').map((item) => {
26	      const trimmed = item.trim();
27	      return trimmed.startsWith('"') && trimmed.endsWith('"')
28	        ? trimmed.slice(1, -1)
29	        : trimmed;
30	    });
31	  }
32	
33	  if (value.startsWith('"') && value.endsWith('"')) {
34	    return value.slice(1, -1);
35	  }
36	
37	  return value;
38	}
