40	function parseYaml(yamlContent: string): Record<string, unknown> {
41	  const lines = yamlContent.split('\n');
42	  const result: Record<string, unknown> = {};
43	
44	  for (const line of lines) {
45	    if (!line.trim() || line.trim().startsWith('#')) continue;
46	
47	    const colonIndex = line.indexOf(':');
48	    if (colonIndex === -1) continue;
49	
50	    const key = line.substring(0, colonIndex).trim();
51	    const value = line.substring(colonIndex + 1).trim();
52	
53	    if (key) {
54	      result[key] = parseYamlValue(value);
55	    }
56	  }
57	
58	  return result;
59	}
60	
61	export function parseFrontmatter(markdown: string): ParsedMarkdown {
62	  const lines = markdown.split('\n');
63	
64	  if (!lines[0]?.trim().startsWith('---')) {
65	    return {
66	      frontmatter: {},
67	      content: markdown,
68	    };
69	  }
70	
71	  let endIndex = -1;
72	  for (let i = 1; i < lines.length; i++) {
73	    if (lines[i]?.trim().startsWith('---')) {
74	      endIndex = i;
75	      break;
76	    }
77	  }
78	
79	  if (endIndex === -1) {
80	    return {
81	      frontmatter: {},
82	      content: markdown,
83	    };
84	  }
85	
86	  const yamlLines = lines.slice(1, endIndex);
87	  const yamlContent = yamlLines.join('\n');
88	  const content = lines.slice(endIndex + 1).join('\n').trim();
89	
90	  const parsed = parseYaml(yamlContent);
91	
92	  return {
93	    frontmatter: parsed as Frontmatter,
94	    content,
95	  };
96	}
