5	async function main(): Promise<void> {
6	  const args = process.argv.slice(2);
7	
8	  if (args.length === 0 || args[0] !== 'build') {
9	    console.error('Usage: ssg build [--content <dir>] [--output <dir>]');
10	    process.exit(1);
11	  }
12	
13	  let contentDir = './content';
14	  let outputDir = './dist';
15	
16	  for (let i = 1; i < args.length; i++) {
17	    if (args[i] === '--content' && args[i + 1]) {
18	      contentDir = args[i + 1];
19	      i++;
20	    } else if (args[i] === '--output' && args[i + 1]) {
21	      outputDir = args[i + 1];
22	      i++;
23	    }
24	  }
25	
26	  try {
